fn imag(val: Vec<(f64, f64)>) -> Vec<f64> {
    // Pre-allocate output with the same length as input for efficiency
    let mut result = Vec::with_capacity(val.len());
    // For each complex number (real, imag) in the input,
    // push only the imaginary part into the result.
    for (_re, im) in val {
        result.push(im);
    }
    result
}

